/* Exact Conway B3/S23 on a toroidal grid. Color and tweening never affect life. */
'use strict';
const $=s=>document.querySelector(s),canvas=$('#field'),ctx=canvas.getContext('2d'),stage=$('#stage');
let cols,rows,cells,ages,previous,dying,cellSize=13,generation=0,mode='jump',paused=false,dark=false,last=0,frame=0,seedNumber=0,pointerDown=false,lastDraw=0;
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
function evolve(board,w,h){const next=new Uint8Array(w*h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let n=0;for(let j=-1;j<=1;j++)for(let i=-1;i<=1;i++){if(i||j)n+=board[((y+j+h)%h)*w+(x+i+w)%w]}const k=y*w+x;next[k]=n===3||(board[k]&&n===2)?1:0}return next}
function resize(){const rect=stage.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);cols=Math.ceil(rect.width/cellSize);rows=Math.ceil(rect.height/cellSize);reset()}
function put(x,y){cells[((y+rows)%rows)*cols+(x+cols)%cols]=1}
function pattern(x,y,arr){for(const [dx,dy]of arr)put(x+dx,y+dy)}
const glider=[[1,0],[2,1],[0,2],[1,2],[2,2]],rPent=[[1,0],[2,0],[0,1],[1,1],[1,2]],acorn=[[1,0],[3,1],[0,2],[1,2],[4,2],[5,2],[6,2]];
function textSeed(text){const off=document.createElement('canvas');off.width=cols;off.height=rows;const c=off.getContext('2d');const size=Math.floor(Math.min(cols*.65,rows*.52));c.font=`900 ${size}px 'Microsoft YaHei',sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillStyle='white';c.fillText(text,cols*.53,rows*.62);const data=c.getImageData(0,0,cols,rows).data;for(let k=0;k<cells.length;k++)if(data[k*4+3]>100)cells[k]=1}
function reset(){cells=new Uint8Array(cols*rows);ages=new Uint16Array(cols*rows);previous=cells.slice();dying=[];generation=0;seedNumber=0;textSeed(mode==='together'?'玩':'跳');for(let i=0;i<9;i++)pattern(Math.floor(Math.random()*cols),Math.floor(rows*.38+Math.random()*rows*.5),i%2?glider:rPent);updateStats()}
function updateStats(){let count=0;for(const v of cells)count+=v;$('#gen').textContent=String(generation).padStart(4,'0');$('#count').textContent=count;$('#state').textContent=paused?'Ⅱ PAUSED':'● EVOLVING'}
function tick(){previous=cells.slice();cells=evolve(cells,cols,rows);dying=[];for(let k=0;k<cells.length;k++){if(previous[k]&&!cells[k])dying.push(k);ages[k]=cells[k]?Math.min(ages[k]+1,65500):0}generation++;updateStats();last=performance.now()}
function seed(x,y){x=Math.floor(x/cellSize);y=Math.floor(y/cellSize);seedNumber++;if(mode==='chase'){pattern(x,y,glider);pattern(x-5,y-5,glider)}else if(mode==='together'){pattern(x-5,y,rPent);pattern(x+3,y,rPent);pattern(x,y+5,glider)}else{pattern(x,y,seedNumber%2?acorn:rPent);pattern(x-4,y-4,glider)}updateStats();$('#toast').classList.add('on');clearTimeout(seed.toast);seed.toast=setTimeout(()=>$('#toast').classList.remove('on'),700)}
function randomSeed(){const r=stage.getBoundingClientRect();seed(r.width*(.2+Math.random()*.6),r.height*(.4+Math.random()*.42))}
function render(now){const w=stage.clientWidth,h=stage.clientHeight;ctx.clearRect(0,0,w,h);ctx.fillStyle=dark?'#fa004827':'#25242635';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){ctx.fillRect(x*cellSize+cellSize/2,y*cellSize+cellSize/2,1,1)}const progress=Math.min(1,(now-last)/(1000/Number($('#speed').value)));for(let k=0;k<cells.length;k++){if(!cells[k])continue;const x=k%cols*cellSize+cellSize/2,y=Math.floor(k/cols)*cellSize+cellSize/2;let size=cellSize-1;const newborn=!previous[k];if(newborn&&!reduce)size*=.55+.45*progress;ctx.save();ctx.translate(x,y);if(newborn&&!reduce)ctx.rotate((1-progress)*.65*((k%3)-1));ctx.fillStyle=dark?(ages[k]<3?'#f3f0e6':'#fa0048'):(ages[k]<3?'#252426':'#00efb2');ctx.fillRect(-size/2,-size/2,size,size);if(ages[k]<2){ctx.fillStyle=dark?'#fa0048':'#f3f0e6';ctx.fillRect(-.9,-.9,1.8,1.8)}ctx.restore()}if(!reduce&&progress<1){ctx.fillStyle=dark?'#fa0048':'#252426';ctx.globalAlpha=(1-progress)*.6;for(const k of dying){const size=(cellSize-2)*(1-progress);ctx.fillRect(k%cols*cellSize+cellSize/2-size/2,Math.floor(k/cols)*cellSize+cellSize/2-size/2,size,size)}ctx.globalAlpha=1}frame=requestAnimationFrame(loop)}
function loop(now){if(!paused&&now-last>=1000/Number($('#speed').value))tick();render(now)}
canvas.addEventListener('pointerdown',e=>{pointerDown=true;canvas.setPointerCapture(e.pointerId);const r=canvas.getBoundingClientRect();seed(e.clientX-r.left,e.clientY-r.top)});canvas.addEventListener('pointermove',e=>{if(!pointerDown||performance.now()-lastDraw<110)return;lastDraw=performance.now();const r=canvas.getBoundingClientRect();seed(e.clientX-r.left,e.clientY-r.top)});canvas.addEventListener('pointerup',()=>pointerDown=false);canvas.addEventListener('pointercancel',()=>pointerDown=false);
$('#jump').onclick=randomSeed;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'继续演化 ▶':'暂停演化 Ⅱ';updateStats()};$('#reset').onclick=reset;$('#step').onclick=()=>{paused=true;$('#pause').textContent='继续演化 ▶';tick()};
const copy={jump:['跳，打破平静。','每次落脚播下一簇细胞。它们相遇、繁衍，找到自己的节奏。','跳一下','CLICK CANVAS / PRESS SPACE TO SEED'],chase:['追，让世界流动。','种下成对的滑翔机。沿途的相遇，改变每一次奔跑的方向。','放出追逐者','DRAG TO LEAVE A TRAIL OF GLIDERS'],together:['一起，长出可能。','把两簇生命放在彼此身边。相同的规则，生长出意外的关系。','一起播种','TWO SEEDS / ONE SHARED PLAYGROUND']};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));const c=copy[mode];$('#modeTitle').textContent=c[0];$('#modeDesc').textContent=c[1];$('#jump').innerHTML=c[2]+' <span>↗</span>';$('#hint').textContent=c[3];reset()});
document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{dark=b.dataset.theme==='dark';document.body.classList.toggle('dark',dark)});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['BUTTON','INPUT'].includes(document.activeElement.tagName)){e.preventDefault();randomSeed()}});
$('#save').onclick=()=>{const out=document.createElement('canvas');out.width=canvas.width;out.height=canvas.height;const c=out.getContext('2d');c.fillStyle=dark?'#242324':'#fa0048';c.fillRect(0,0,out.width,out.height);c.drawImage(canvas,0,0);const ratio=canvas.width/stage.clientWidth;c.scale(ratio,ratio);c.fillStyle=dark?'#fa0048':'#252426';c.font='900 38px Arial';c.fillText('LIFE IS A PLAYGROUND.',28,60);c.font='12px monospace';c.fillText('CONWAY B3/S23 / GENERATION '+generation,28,88);const a=document.createElement('a');a.download='playground-generation-'+generation+'.png';a.href=out.toDataURL('image/png');a.click()};
let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(resize,180)});resize();if(reduce){paused=true;$('#pause').textContent='继续演化 ▶';updateStats()}requestAnimationFrame(loop);
